# ADR-062 and DDD-0015 dual-model review

## Verified reviewers

| Lane | Live provider/model evidence | Effort | Final verdict |
|---|---|---|---|
| Fable 5 | Claude CLI canonical model `claude-fable-5`, provider `firstParty`, session `9c38f28e-ed53-4c44-867b-f9faab401dc3` | Medium | SIGN-WITH-CHANGES; exact changes applied |
| GPT-5.6 Sol | Codex model `gpt-5.6-sol` | Medium | SIGN |

No alias was guessed and no substitute model was used.

## Corrections incorporated before acceptance

- required one same-reducer npm observation before GitHub latest intent;
- removed special re-promotion states and made compensated routing depend on fresh GitHub state;
- separated immutable candidate payload identity from its signed evidence envelope;
- made sequence-zero prior-generation evidence immutable across retries;
- removed decorative fencing and defined create-only receipt CAS semantics;
- made draft creation the sole idempotent bootstrap exception before the first receipt;
- resolved published tag identity by SHA instead of trusting `target_commitish`;
- scoped host matrices to one candidate run and one final public-artifact run;
- distinguished a healthy published-non-latest state from a draft that requires compensation;
- required fresh dual-provider observation rather than implying an atomic cross-provider snapshot;
- defined the precise no-further-mutation rule after a receipt CAS loss.

## Acceptance

Both governing documents describe the same build-once, persist-once, resume-by-observation release
transaction and have no remaining implementation-blocking contradiction. Implementation and
Agentic QE must still prove conformance before publication.

import { test } from 'vitest';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { planUserModelHooks, applyUserModelHooks, shellQuote } from '../../scripts/user-model-hook-install.mjs';

function fixture(run) {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), 'weekly hook home '));
  fs.mkdirSync(path.join(home, '.claude/model-router/bin'), { recursive: true });
  fs.mkdirSync(path.join(home, '.codex'));
  fs.writeFileSync(path.join(home, '.claude/model-router/bin/user-model-prompt-hook.mjs'), '// fixture');
  try { run(home); } finally { fs.rmSync(home, { recursive: true, force: true }); }
}

function write(home, relative, value) { fs.writeFileSync(path.join(home, relative), JSON.stringify(value)); }

test('dry plan is inert; native registrations append preserving private settings and hook indices', () => fixture(home => {
  const verify = { hooks: [{ type: 'command', command: 'node ~/.codex/hooks/verify-request.mjs', timeout: 5 }] };
  write(home, '.codex/hooks.json', { hooks: { UserPromptSubmit: [verify], Stop: [] }, privateSetting: 123 });
  write(home, '.claude/settings.json', { env: { PRIVATE: 'synthetic' }, hooks: { Stop: [] } });
  fs.chmodSync(path.join(home, '.claude/settings.json'), 0o640);
  // Windows reports its own mode; preserve the observed host value rather than assuming Unix bits.
  const initialMode = fs.statSync(path.join(home, '.claude/settings.json')).mode & 0o777;
  if (process.platform !== 'win32') assert.equal(initialMode, 0o640);
  const before = fs.readFileSync(path.join(home, '.codex/hooks.json'), 'utf8');
  const plan = planUserModelHooks({ home });
  assert.equal(fs.readFileSync(path.join(home, '.codex/hooks.json'), 'utf8'), before);
  const receipt = applyUserModelHooks(plan);
  assert.equal(receipt.written.length, 2);
  const codex = JSON.parse(fs.readFileSync(path.join(home, '.codex/hooks.json')));
  assert.deepEqual(codex.hooks.UserPromptSubmit[0], verify);
  assert.equal(codex.privateSetting, 123);
  assert.equal(codex.hooks.UserPromptSubmit[1].matcher, undefined);
  assert.equal(codex.hooks.UserPromptSubmit[1].hooks[0].timeout, 3);
  const claude = JSON.parse(fs.readFileSync(path.join(home, '.claude/settings.json')));
  assert.deepEqual(claude.env, { PRIVATE: 'synthetic' });
  assert.match(claude.hooks.UserPromptSubmit[0].hooks[0].command, / --claude$/);
  assert.equal(fs.statSync(path.join(home, '.claude/settings.json')).mode & 0o777, initialMode);
  assert.equal(fs.readFileSync(receipt.written[1].backup, 'utf8'), before);
  assert.equal(planUserModelHooks({ home }).changes.some(change => change.changed), false);
}));

test('logical node alias of trusted executable recognizes exact existing unmanaged registration', () => fixture(home => {
  const script = path.join(home, '.claude/model-router/bin/user-model-prompt-hook.mjs');
  const bin = path.join(home, 'bin'); fs.mkdirSync(bin); fs.symlinkSync(process.execPath, path.join(bin, 'node'));
  write(home, '.claude/settings.json', { hooks: { UserPromptSubmit: [{ hooks: [{ type: 'command', command: `node ${shellQuote(script)} --claude`, timeout: 3 }] }] } });
  const plan = planUserModelHooks({ home, searchPath: bin });
  assert.equal(plan.changes[0].changed, false);
}));

test('custom overrides and mixed shell commands referencing target fail without clobbering', () => fixture(home => {
  const script = path.join(home, '.claude/model-router/bin/user-model-prompt-hook.mjs');
  const commands = [`node ${shellQuote(script)} --claude && echo custom`, `node ${shellQuote(script)} --claude --custom`, `echo ${shellQuote(script)}`];
  for (const command of commands) {
    write(home, '.claude/settings.json', { hooks: { UserPromptSubmit: [{ hooks: [{ type: 'command', command }] }] } });
    const before = fs.readFileSync(path.join(home, '.claude/settings.json'), 'utf8');
    assert.throws(() => planUserModelHooks({ home }), /Unowned model-hook override/);
    assert.equal(fs.readFileSync(path.join(home, '.claude/settings.json'), 'utf8'), before);
  }
}));

test('duplicate exact ownership, malformed JSON/schema and symlink targets fail closed', () => fixture(home => {
  const file = path.join(home, '.claude/settings.json');
  fs.writeFileSync(file, '{'); assert.throws(() => planUserModelHooks({ home }), /Malformed JSON/);
  write(home, '.claude/settings.json', { hooks: [] }); assert.throws(() => planUserModelHooks({ home }), /Malformed hooks/);
  write(home, '.claude/settings.json', { hooks: { UserPromptSubmit: null } }); assert.throws(() => planUserModelHooks({ home }), /Malformed UserPromptSubmit/);
  const script = path.join(home, '.claude/model-router/bin/user-model-prompt-hook.mjs');
  const group = { hooks: [{ type: 'command', command: `${shellQuote(process.execPath)} ${shellQuote(script)} --claude` }] };
  write(home, '.claude/settings.json', { hooks: { UserPromptSubmit: [group, group] } });
  assert.throws(() => planUserModelHooks({ home }), /Ambiguous/);
  fs.unlinkSync(file); fs.symlinkSync(path.join(home, '.codex/hooks.json'), file);
  assert.throws(() => planUserModelHooks({ home }), /Symlink/);
}));

test('stale plans cannot overwrite concurrent settings; missing runtime cannot apply', () => fixture(home => {
  const plan = planUserModelHooks({ home });
  write(home, '.codex/hooks.json', { concurrent: true });
  assert.throws(() => applyUserModelHooks(plan), /Config changed/);
  assert.equal(fs.existsSync(path.join(home, '.claude/settings.json')), false);
  const fresh = planUserModelHooks({ home }); fs.unlinkSync(fresh.script);
  assert.throws(() => applyUserModelHooks(fresh), /runtime/);
}));

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, expect, it } from 'vitest';
import { resolveInstalledCanaryCitation } from '../../scripts/retrieval-canary.mjs';
import { digest, sha256File } from '../../scripts/coverage-integrity.mjs';
const roots = [];
afterEach(() => roots.splice(0).forEach((dir) => fs.rmSync(dir, { recursive: true, force: true })));
function fixture() {
  const kbDir = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'installed-citation-'))); roots.push(kbDir);
  const passage = { path: 'src/a.mjs', text: 'the exact installed passage' };
  const expected = { repo: 'sample', path: passage.path, passageSha256: digest(passage) };
  return { kbDir, passage, expected, matched: { repo: 'SAMPLE', path: passage.path, text: passage.text } };
}
it.each(['passages', 'big.passages'])('preserves exact record/file evidence for installed %s files', async (suffix) => {
  const f = fixture(); const file = path.join(f.kbDir, `sample.${suffix}.jsonl`);
  fs.writeFileSync(file, 'invalid json\n' + JSON.stringify(f.passage) + '\n');
  expect(await resolveInstalledCanaryCitation(f)).toEqual({ resolved: true,
    evidence: { passageSha256: digest(f.passage), passageFileSha256: sha256File(file), hitContentSha256: digest(f.matched.text) } });
});
it.each(['missing', 'passage-mutant', 'wrong-path', 'wrong-repo'])('preserves fail-closed %s semantics', async (mutant) => {
  const f = fixture();
  if (mutant !== 'missing') fs.writeFileSync(path.join(f.kbDir, 'sample.passages.jsonl'), JSON.stringify(f.passage));
  if (mutant === 'passage-mutant') f.expected.passageSha256 = '0'.repeat(64);
  if (mutant === 'wrong-path') f.matched.path = 'other';
  if (mutant === 'wrong-repo') f.matched.repo = 'other';
  expect(await resolveInstalledCanaryCitation(f)).toEqual({ resolved: false });
});
it('requires an explicit absolute installed context, never an ambient store', async () => {
  const f = fixture(); delete f.kbDir;
  await expect(resolveInstalledCanaryCitation(f)).rejects.toThrow(/must be absolute/);
});
it('rejects citation content absent from the actual returned hit', async () => {
  const f = fixture();
  fs.writeFileSync(path.join(f.kbDir, 'sample.passages.jsonl'), JSON.stringify(f.passage));
  f.matched.text = 'a different result body';
  expect(await resolveInstalledCanaryCitation(f)).toEqual({ resolved: false });
});
it.each(['file', 'parent'])('rejects an external %s symlink instead of calling it installed evidence', async (kind) => {
  const f = fixture();
  const outside = fs.mkdtempSync(path.join(os.tmpdir(), 'outside-citation-')); roots.push(outside);
  const file = path.join(outside, 'sample.passages.jsonl');
  fs.writeFileSync(file, JSON.stringify(f.passage));
  if (kind === 'file') fs.symlinkSync(file, path.join(f.kbDir, 'sample.passages.jsonl'));
  else { const linked = path.join(f.kbDir, 'linked'); fs.symlinkSync(outside, linked, 'junction'); f.kbDir = linked; }
  await expect(resolveInstalledCanaryCitation(f)).rejects.toThrow(/symlink|containment/);
});
it('the publication adapter delegates to the same resolver with its installed context and cache', () => {
  const source = fs.readFileSync('scripts/publication-receipt.mjs', 'utf8');
  expect(source).toContain('return resolveInstalledCanaryCitation({ kbDir: context.kb, matched, expected, passageFileDigests });');
  expect(source).not.toContain('readline.createInterface');
});

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';
import { afterEach, describe, expect, it } from 'vitest';
import { recoverIncompleteStorageTransactions, runStorageTransaction,
  managedStorageInventory, treeIdentity } from '../../kb/update-storage-transaction.mjs';

const MODULE = pathToFileURL(path.resolve(import.meta.dirname, '../../kb/update-storage-transaction.mjs')).href;

const roots = [];
function fixture({ same = false } = {}) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'rnb-storage-tx-'));
  roots.push(root);
  const live = path.join(root, 'kb');
  const source = path.join(root, 'incoming');
  fs.mkdirSync(live); fs.mkdirSync(source);
  fs.writeFileSync(path.join(live, 'public.txt'), 'old');
  fs.writeFileSync(path.join(source, 'public.txt'), same ? 'old' : 'new');
  return { root, live, source, before: treeIdentity(live) };
}

afterEach(() => roots.splice(0).forEach((root) => fs.rmSync(root, { recursive: true, force: true })));

describe('atomic KB storage transaction', () => {
  it('measures preserved and unresolved installer trees without making them cleanup eligible', () => {
    const f = fixture();
    const names = ['kb.install-preserved-old', 'kb.install-prior-crashed', '.kb.install-stage-partial'];
    for (const name of names) {
      const dir = path.join(f.root, name);
      fs.mkdirSync(dir);
      fs.writeFileSync(path.join(dir, 'private.txt'), 'private bytes');
      fs.symlinkSync(f.source, path.join(dir, 'external-link'));
    }
    const external = path.join(f.root, 'kb.install-preserved-link');
    fs.symlinkSync(f.source, external);
    const inventory = managedStorageInventory(f.live);
    expect(inventory.additionalFullCorpusCopyCount).toBe(4);
    const observed = inventory.fullCorpusCopies.filter((row) => row.kind.startsWith('installer-'));
    expect(observed).toHaveLength(4);
    expect(observed.every((row) => row.automaticCleanupEligible === false)).toBe(true);
    expect(observed.reduce((sum, row) => sum + row.symlinkCount, 0)).toBe(4);
    expect(observed.reduce((sum, row) => sum + row.fileCount, 0)).toBe(3);
    expect(inventory.additionalFullCorpusBytes).toBe(3 * Buffer.byteLength('private bytes') + 4 * Buffer.byteLength(f.source));
    expect(fs.readFileSync(path.join(f.source, 'public.txt'), 'utf8')).toBe('new');
    expect(fs.lstatSync(external).isSymbolicLink()).toBe(true);
  });

  it('builds and validates off to the side, then commits one rename activation', () => {
    const f = fixture();
    const result = runStorageTransaction({ liveDir: f.live, sourceDir: f.source, transactionId: 'apply-1',
      prepareCandidate: ({ candidateDir }) => fs.writeFileSync(path.join(candidateDir, 'private.txt'), 'preserved'),
      validateCandidate: ({ dir }) => ({ valid: fs.readFileSync(path.join(dir, 'private.txt'), 'utf8') === 'preserved' }),
    });
    expect(result.terminalVerdict).toBe('applied');
    expect(result.storageDelta).toMatchObject({ redundantCopyCount: 0, redundantBytes: 0,
      cleanupPending: false });
    expect(fs.readFileSync(path.join(f.live, 'public.txt'), 'utf8')).toBe('new');
    expect(fs.readFileSync(path.join(f.live, 'private.txt'), 'utf8')).toBe('preserved');
    expect(fs.existsSync(result.paths.rollback)).toBe(false);
    expect(fs.existsSync(result.paths.candidate)).toBe(false);
  });

  it('returns an exact-byte noop without creating a rollback directory', () => {
    const f = fixture({ same: true });
    const result = runStorageTransaction({ liveDir: f.live, sourceDir: f.source, transactionId: 'noop-1' });
    expect(result.terminalVerdict).toBe('noop');
    expect(result.storageDelta).toMatchObject({ activeBytesDelta: 0, redundantCopyCount: 0 });
    expect(treeIdentity(f.live)).toEqual(f.before);
    expect(fs.existsSync(result.paths.rollback)).toBe(false);
  });

  it('leaves live byte-identical when candidate preparation or validation fails', () => {
    for (const [id, prepareCandidate, validateCandidate] of [
      ['prepare-fail', () => { throw new Error('overlay failed'); }, undefined],
      ['validate-fail', undefined, () => ({ valid: false, failures: ['coverage failed'] })],
    ]) {
      const f = fixture();
      expect(() => runStorageTransaction({ liveDir: f.live, sourceDir: f.source, transactionId: id,
        ...(prepareCandidate ? { prepareCandidate } : {}), ...(validateCandidate ? { validateCandidate } : {}) })).toThrow();
      expect(treeIdentity(f.live)).toEqual(f.before);
    }
  });

  it('restores and verifies prior bytes when activation or live verification fails', () => {
    for (const [id, checkpoint, validateLive] of [
      ['rename-fail', (phase) => { if (phase === 'OLD_RENAMED') throw new Error('injected rename boundary failure'); }, undefined],
      ['live-fail', undefined, () => ({ valid: false, failures: ['guard failed'] })],
    ]) {
      const f = fixture();
      expect(() => runStorageTransaction({ liveDir: f.live, sourceDir: f.source, transactionId: id,
        ...(checkpoint ? { checkpoint } : {}), ...(validateLive ? { validateLive } : {}) })).toThrow(/restored and verified/);
      expect(treeIdentity(f.live)).toEqual(f.before);
      expect(fs.readdirSync(f.root).filter((name) => /\.(?:next|rollback|failed)-/.test(name))).toEqual([]);
    }
  });

  it('rejects unsafe transaction identifiers before creating paths', () => {
    const f = fixture();
    expect(() => runStorageTransaction({ liveDir: f.live, sourceDir: f.source, transactionId: '../escape' }))
      .toThrow(/unsafe/);
    expect(treeIdentity(f.live)).toEqual(f.before);
  });

  it.each(['LOCKED', 'CANDIDATE_BUILDING', 'CANDIDATE_VERIFIED', 'OLD_RENAME_STARTED',
    'OLD_RENAMED', 'ACTIVATED_UNRECEIPTED', 'ACTIVATED', 'LIVE_VERIFIED', 'ROLLBACK_REMOVED'])
  ('recovers a process killed after %s before admitting another transaction', (killAt) => {
    const f = fixture();
    const script = `import {runStorageTransaction} from ${JSON.stringify(MODULE)};
runStorageTransaction({liveDir:${JSON.stringify(f.live)},sourceDir:${JSON.stringify(f.source)},transactionId:'killed-${killAt.toLowerCase()}',
checkpoint:(phase)=>{if(phase===${JSON.stringify(killAt)})process.exit(93);}});`;
    const child = spawnSync(process.execPath, ['--input-type=module', '-e', script], { encoding: 'utf8' });
    expect(child.status).toBe(93);
    const recovered = recoverIncompleteStorageTransactions(f.live);
    const preservesCandidate = ['LIVE_VERIFIED', 'ROLLBACK_REMOVED'].includes(killAt);
    const expectedVerdict = preservesCandidate ? 'applied' : 'interrupted-run-restored';
    expect(recovered).toHaveLength(1);
    const recoveredFrom = killAt === 'ROLLBACK_REMOVED' ? 'LIVE_VERIFIED'
      : killAt === 'ACTIVATED_UNRECEIPTED' ? 'OLD_RENAMED' : killAt;
    expect(recovered[0]).toMatchObject({ transactionId: `killed-${killAt.toLowerCase()}`, from: recoveredFrom,
      terminalVerdict: expectedVerdict, storageDelta: { redundantCopyCount: 0 } });
    if (preservesCandidate) {
      expect(fs.readFileSync(path.join(f.live, 'public.txt'), 'utf8')).toBe('new');
    } else expect(treeIdentity(f.live)).toEqual(f.before);
    expect(fs.readdirSync(f.root).filter((name) => /\.next-|\.rollback-|\.failed-/.test(name))).toEqual([]);
  });

  it('recovers a process killed WHILE building the candidate (the long phase), without discarding or bricking', () => {
    // MEASURED 2026-09-30 (scripts/customer-state-matrix.mjs, transaction=killed-during-candidate-build): the
    // real 4.3.39 `--update` SIGKILLed while kb.next-* existed (lid close, Ctrl-C, detach.mjs TTL). The
    // checkpoint kills above all fire at phase BOUNDARIES, where no unsealed candidate exists. Mid-phase the
    // candidate exists with no sealed identity, so recovery wrote RECOVERY_REQUIRED, and from then on every
    // update refused "requires manual recovery" (the installer fell back to a fresh reinstall each time).
    const f = fixture();
    const script = `import {runStorageTransaction} from ${JSON.stringify(MODULE)};
runStorageTransaction({liveDir:${JSON.stringify(f.live)},sourceDir:${JSON.stringify(f.source)},transactionId:'killed-mid-build',
prepareCandidate:()=>{process.exit(93);}});`;
    expect(spawnSync(process.execPath, ['--input-type=module', '-e', script], { encoding: 'utf8' }).status).toBe(93);
    const candidate = path.join(f.root, 'kb.next-killed-mid-build');
    expect(fs.existsSync(candidate)).toBe(true);
    // Even bytes written into it after the crash survive: quarantine moves, it never deletes.
    fs.writeFileSync(path.join(candidate, 'post-crash-private.txt'), 'must survive recovery');
    const unsealed = treeIdentity(candidate);

    expect(recoverIncompleteStorageTransactions(f.live)).toMatchObject([{ transactionId: 'killed-mid-build',
      from: 'CANDIDATE_BUILDING', terminalVerdict: 'interrupted-run-restored' }]);
    expect(treeIdentity(f.live)).toEqual(f.before);
    // Nothing unproven is deleted: the unsealed bytes are quarantined intact, beside live, and named.
    const quarantine = path.join(f.root, 'kb.failed-killed-mid-build');
    expect(fs.existsSync(candidate)).toBe(false);
    expect(treeIdentity(quarantine)).toEqual(unsealed);
    // And it is settled: the next update is admitted and lands.
    expect(recoverIncompleteStorageTransactions(f.live)).toEqual([]);
    expect(runStorageTransaction({ liveDir: f.live, sourceDir: f.source, transactionId: 'after-kill' }))
      .toMatchObject({ terminalVerdict: 'applied' });
    expect(fs.readFileSync(path.join(f.live, 'public.txt'), 'utf8')).toBe('new');
    // That next run released the quarantine (bytes unchanged since sealed): no permanent full-size copy.
    expect(fs.existsSync(quarantine)).toBe(false);
    expect(fs.readdirSync(f.root).filter((name) => /\.next-|\.rollback-|\.failed-/.test(name))).toEqual([]);
  });

  const killMidBuild = (f, id) => {
    const script = `import {runStorageTransaction} from ${JSON.stringify(MODULE)};
runStorageTransaction({liveDir:${JSON.stringify(f.live)},sourceDir:${JSON.stringify(f.source)},transactionId:'${id}',
prepareCandidate:()=>{process.exit(93);}});`;
    expect(spawnSync(process.execPath, ['--input-type=module', '-e', script], { encoding: 'utf8' }).status).toBe(93);
  };

  it('TEETH: a mid-build kill whose LIVE tree changed afterwards still refuses, and moves nothing', () => {
    const f = fixture();
    killMidBuild(f, 'live-tampered');
    fs.writeFileSync(path.join(f.live, 'public.txt'), 'changed after the crash');
    const candidate = path.join(f.root, 'kb.next-live-tampered');
    const before = treeIdentity(candidate);
    expect(() => recoverIncompleteStorageTransactions(f.live)).toThrow(/interrupted live tree identity differs/);
    expect(treeIdentity(candidate)).toEqual(before);
    expect(fs.existsSync(path.join(f.root, 'kb.failed-live-tampered'))).toBe(false);
  });

  it('TEETH: a quarantine whose bytes changed after it was sealed is never released', () => {
    const f = fixture();
    killMidBuild(f, 'q-tampered');
    recoverIncompleteStorageTransactions(f.live);
    const quarantine = path.join(f.root, 'kb.failed-q-tampered');
    fs.writeFileSync(path.join(quarantine, 'added-later.txt'), 'keep me');
    recoverIncompleteStorageTransactions(f.live);
    expect(fs.readFileSync(path.join(quarantine, 'added-later.txt'), 'utf8')).toBe('keep me');
  });

  it('recovers a process killed after live was renamed but before OLD_RENAMED was receipted', () => {
    const f = fixture();
    const script = `import {runStorageTransaction} from ${JSON.stringify(MODULE)};
runStorageTransaction({liveDir:${JSON.stringify(f.live)},sourceDir:${JSON.stringify(f.source)},transactionId:'unreceipted-old-rename',
checkpoint:(phase)=>{if(phase==='OLD_RENAMED_UNRECEIPTED')process.exit(93);}});`;
    const child = spawnSync(process.execPath, ['--input-type=module', '-e', script], { encoding: 'utf8' });
    expect(child.status).toBe(93);

    expect(recoverIncompleteStorageTransactions(f.live)).toMatchObject([{
      transactionId: 'unreceipted-old-rename', from: 'OLD_RENAME_STARTED',
      terminalVerdict: 'interrupted-run-restored', storageDelta: { redundantCopyCount: 0 },
    }]);
    expect(treeIdentity(f.live)).toEqual(f.before);
    expect(fs.readdirSync(f.root).filter((name) => /\.next-|\.rollback-|\.failed-/.test(name))).toEqual([]);
  });

  // CANDIDATE_BUILDING with a candidate present is covered by the mid-build kill test above: the bytes are
  // preserved by quarantine rather than by refusing every later update.
  it.each([
    ['CANDIDATE_VERIFIED', 'candidate'],
    ['OLD_RENAME_STARTED', 'candidate'],
    ['OLD_RENAMED', 'candidate'],
    ['OLD_RENAMED', 'rollback'],
    ['ACTIVATED_UNRECEIPTED', 'live'],
    ['ACTIVATED', 'live'],
    ['LIVE_VERIFIED', 'rollback'],
  ])('preserves all trees when %s recovery finds changed %s bytes', (killAt, target) => {
    const f = fixture();
    const script = `import {runStorageTransaction} from ${JSON.stringify(MODULE)};
runStorageTransaction({liveDir:${JSON.stringify(f.live)},sourceDir:${JSON.stringify(f.source)},transactionId:'tampered',
checkpoint:(phase)=>{if(phase===${JSON.stringify(killAt)})process.exit(93);}});`;
    expect(spawnSync(process.execPath, ['--input-type=module', '-e', script], { encoding: 'utf8' }).status).toBe(93);
    const receipts = path.join(f.root, '.kb.update-transactions', 'tampered');
    const latest = JSON.parse(fs.readFileSync(path.join(receipts, fs.readdirSync(receipts).sort().at(-1)), 'utf8'));
    fs.mkdirSync(latest.paths[target], { recursive: true });
    fs.writeFileSync(path.join(latest.paths[target], 'post-crash-private.txt'), 'must survive recovery');
    const before = Object.fromEntries(['live', 'candidate', 'rollback', 'failed'].map((name) => [name,
      fs.existsSync(latest.paths[name]) ? treeIdentity(latest.paths[name]) : null]));

    expect(() => recoverIncompleteStorageTransactions(f.live)).toThrow(/identity|sealed receipt/);
    for (const [name, identity] of Object.entries(before)) {
      expect(fs.existsSync(latest.paths[name])).toBe(identity !== null);
      if (identity) expect(treeIdentity(latest.paths[name])).toEqual(identity);
    }
    const final = JSON.parse(fs.readFileSync(path.join(receipts, fs.readdirSync(receipts).sort().at(-1)), 'utf8'));
    expect(final.state).toBe('RECOVERY_REQUIRED');
  });

  it('preserves verified live bytes while rollback cleanup is pending and completes on recovery', () => {
    const f = fixture();
    const result = runStorageTransaction({ liveDir: f.live, sourceDir: f.source,
      transactionId: 'cleanup-pending', removeRollback: () => { throw new Error('busy'); } });
    expect(result).toMatchObject({ terminalVerdict: 'cleanup-pending', cleanupPending: true,
      storageDelta: { redundantCopyCount: 1, cleanupPending: true } });
    expect(fs.readFileSync(path.join(f.live, 'public.txt'), 'utf8')).toBe('new');
    expect(recoverIncompleteStorageTransactions(f.live)).toMatchObject([{
      transactionId: 'cleanup-pending', from: 'CLEANUP_PENDING', terminalVerdict: 'applied',
      storageDelta: { redundantCopyCount: 0, cleanupPending: false },
    }]);
    expect(fs.readFileSync(path.join(f.live, 'public.txt'), 'utf8')).toBe('new');
  });

  it('counts planted managed backups globally and rejects symbolic-link copies', () => {
    const f = fixture({ same: true });
    const backup = `${f.live}.bak-old`;
    fs.cpSync(f.live, backup, { recursive: true });
    expect(managedStorageInventory(f.live)).toMatchObject({ additionalFullCorpusCopyCount: 1,
      additionalFullCorpusBytes: f.before.bytes });
    const result = runStorageTransaction({ liveDir: f.live, sourceDir: f.source, transactionId: 'global-count' });
    expect(result.storageDelta).toMatchObject({ redundantCopyCount: 1, redundantBytes: f.before.bytes });
    fs.rmSync(backup, { recursive: true });
    fs.symlinkSync(f.live, backup);
    expect(() => managedStorageInventory(f.live)).toThrow(/not a trusted directory/);
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import * as models from '../../kb/model-requirements.mjs';

const roots = [];
afterEach(() => {
  vi.restoreAllMocks();
  for (const root of roots.splice(0)) fs.rmSync(root, { recursive: true, force: true });
});
function fixture() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'model-preservation-'));
  roots.push(root);
  return root;
}

describe('S4 does not introduce destructive model-cache optimization', () => {
  it('cannot reclaim an ancestor of the canonical cache', () => {
    const legacy = fixture();
    const canonical = path.join(legacy, 'canonical');
    fs.mkdirSync(canonical);
    // The restored historical implementation accepts an empty descendant during verification
    // and recursively deletes its ancestor, including the canonical directory itself.
    if (models.reclaimRedundantModelCache) models.reclaimRedundantModelCache(legacy, canonical);
    expect(fs.existsSync(canonical)).toBe(true);
    expect(models.reclaimRedundantModelCache).toBeUndefined();
  });

  for (const failure of ['EIO', 'EXDEV']) {
    it(`preserves an already good model when link/copy operations fail with ${failure}`, () => {
      const root = fixture();
      const model = models.BGE_MODEL;
      const destination = models.modelPath(root, model);
      for (const file of ['config.json', 'tokenizer.json', 'onnx/model_quantized.onnx']) {
        for (const revision of ['', 'pinned']) {
          const target = path.join(destination, revision, file);
          fs.mkdirSync(path.dirname(target), { recursive: true });
          fs.writeFileSync(target, `${revision || 'good'}:${file}`);
        }
      }
      const fail = () => { throw Object.assign(new Error('injected filesystem failure'), { code: failure }); };
      vi.spyOn(fs, 'linkSync').mockImplementation(fail);
      vi.spyOn(fs, 'copyFileSync').mockImplementation(fail);
      vi.spyOn(fs, 'cpSync').mockImplementation(fail);
      let error;
      try { models.materializeModelRevision(root, model, 'pinned'); } catch (caught) { error = caught; }
      for (const file of ['config.json', 'tokenizer.json', 'onnx/model_quantized.onnx']) {
        expect(fs.existsSync(path.join(destination, file))).toBe(true);
        expect(fs.readFileSync(path.join(destination, file), 'utf8')).toBe(`good:${file}`);
      }
      expect(error).toBeUndefined();
      expect(fs.linkSync).not.toHaveBeenCalled();
      expect(fs.copyFileSync).not.toHaveBeenCalled();
      expect(fs.cpSync).not.toHaveBeenCalled();
    });
  }

  it('does not add model-cache reclamation to doctor', () => {
    const installer = fs.readFileSync(new URL('../../bin/install.mjs', import.meta.url), 'utf8');
    expect(installer.includes('reclaimRedundantModelCache')).toBe(false);
  });
});

// tests/unit/model-cache-cold.test.mjs — proves the capability battery tells a COLD model cache
// (embedder never downloaded, expected on a fresh machine) apart from a real retrieval OUTAGE.
//
// The bug (docs/4.0-READINESS.md §6 item 1): a cold cache made every battery question print the same
// "(no hit)" a genuine outage prints, so a healthy brain on a fresh machine looked broken. The fix is
// evidence-based — the embedder file is on disk or it is not — and the load-bearing property is the
// ASYMMETRY: cold requires no-hit AND model-absent, so an outage (model PRESENT, retrieval dead) can
// never be softened to "cold". These tests break that guard to confirm it fails on masked outages.
// (Repo names below are neutral placeholders — the classifier is name-agnostic.)
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';
import {
  resolveModelCache,
  requiredEmbedderModels,
  modelPresent,
  classifyBattery,
  EMBEDDER_REL,
  BGE_EMBEDDER_REL,
} from '../../plugin/test/model-cache.mjs';
import {
  configureTransformersModel,
  materializeModelRevision,
  modelCacheReady,
} from '../../kb/model-requirements.mjs';

let tmp;
const savedEnv = {};
const ENV_KEYS = ['KB_MODEL_CACHE', 'RUVNET_BRAIN_HOME'];
beforeEach(() => {
  tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'mcc-test-'));
  for (const k of ENV_KEYS) savedEnv[k] = process.env[k];
});
afterEach(() => {
  fs.rmSync(tmp, { recursive: true, force: true });
  for (const k of ENV_KEYS) { if (savedEnv[k] === undefined) delete process.env[k]; else process.env[k] = savedEnv[k]; }
});

describe('resolveModelCache — mirrors the MCP server (server.mjs) cache resolution', () => {
  it('honors KB_MODEL_CACHE verbatim (explicit override wins)', () => {
    expect(resolveModelCache({ KB_MODEL_CACHE: '/explicit/models' })).toBe('/explicit/models');
  });
  it('falls back to <RUVNET_BRAIN_HOME>/models when no KB_MODEL_CACHE', () => {
    expect(resolveModelCache({ RUVNET_BRAIN_HOME: '/brain' })).toBe(path.join('/brain', 'models'));
  });
  it('falls back to ~/.cache/ruvnet-brain/models with neither env set (the MCP default)', () => {
    expect(resolveModelCache({})).toBe(path.join(os.homedir(), '.cache', 'ruvnet-brain', 'models'));
  });
});

describe('modelPresent — the one honest signal: is the embedder on disk?', () => {
  it('false when the embedder leaf dir is absent (cold cache)', () => {
    expect(modelPresent(tmp)).toBe(false);
  });
  it('true only when Xenova/all-MiniLM-L6-v2 actually exists (warm cache)', () => {
    fs.mkdirSync(path.join(tmp, EMBEDDER_REL), { recursive: true });
    expect(modelPresent(tmp)).toBe(true);
  });
  it('the reranker being present does NOT warm the query path (must still read cold)', () => {
    // A machine can hold the cross-encoder (Xenova/ms-marco-MiniLM-L-6-v2) yet lack the embedder —
    // exactly the state of ~/.cache/ruvnet-brain/models that produced this bug. It must read cold.
    fs.mkdirSync(path.join(tmp, 'Xenova', 'ms-marco-MiniLM-L-6-v2'), { recursive: true });
    expect(modelPresent(tmp)).toBe(false);
  });
});

describe('requiredEmbedderModels — follows the installed RVF sidecars', () => {
  it('requires BGE when canonical big stores declare BGE, not the unrelated MiniLM fallback', () => {
    fs.writeFileSync(path.join(tmp, 'ruflo.big.rvf'), '');
    fs.writeFileSync(
      path.join(tmp, 'ruflo.big.rvf.embed.json'),
      JSON.stringify({ model: 'Xenova/bge-base-en-v1.5', dimensions: 768 }),
    );
    expect(requiredEmbedderModels(tmp)).toEqual(['Xenova/bge-base-en-v1.5']);
    fs.mkdirSync(path.join(tmp, EMBEDDER_REL), { recursive: true });
    expect(modelPresent(tmp, requiredEmbedderModels(tmp))).toBe(false);
    fs.mkdirSync(path.join(tmp, BGE_EMBEDDER_REL), { recursive: true });
    expect(modelPresent(tmp, requiredEmbedderModels(tmp))).toBe(true);
  });

  it('deduplicates models and ignores orphan sidecars whose RVF is absent', () => {
    for (const name of ['a', 'b']) {
      fs.writeFileSync(path.join(tmp, `${name}.big.rvf`), '');
      fs.writeFileSync(
        path.join(tmp, `${name}.big.rvf.embed.json`),
        JSON.stringify({ model: 'Xenova/bge-base-en-v1.5' }),
      );
    }
    fs.writeFileSync(
      path.join(tmp, 'orphan.rvf.embed.json'),
      JSON.stringify({ model: 'Xenova/all-MiniLM-L6-v2' }),
    );
    expect(requiredEmbedderModels(tmp)).toEqual(['Xenova/bge-base-en-v1.5']);
  });

  it('matches the reader: a canonical big store supersedes its legacy small store', () => {
    fs.writeFileSync(path.join(tmp, 'ruflo.rvf'), '');
    fs.writeFileSync(
      path.join(tmp, 'ruflo.rvf.embed.json'),
      JSON.stringify({ model: 'Xenova/all-MiniLM-L6-v2' }),
    );
    fs.writeFileSync(path.join(tmp, 'ruflo.big.rvf'), '');
    fs.writeFileSync(
      path.join(tmp, 'ruflo.big.rvf.embed.json'),
      JSON.stringify({ model: 'Xenova/bge-base-en-v1.5' }),
    );
    expect(requiredEmbedderModels(tmp)).toEqual(['Xenova/bge-base-en-v1.5']);
  });

  it('falls back to MiniLM only when no readable installed-store sidecar exists', () => {
    expect(requiredEmbedderModels(tmp)).toEqual(['Xenova/all-MiniLM-L6-v2']);
    fs.writeFileSync(path.join(tmp, 'broken.rvf'), '');
    fs.writeFileSync(path.join(tmp, 'broken.rvf.embed.json'), '{bad json');
    expect(requiredEmbedderModels(tmp)).toEqual(['Xenova/all-MiniLM-L6-v2']);
  });
});

describe('configureTransformersModel — reads and downloads through the same cache', () => {
  it('sets both localModelPath and cacheDir to the detector-visible cache', () => {
    const T = { env: {} };
    const r = configureTransformersModel(T, tmp, 'Xenova/bge-base-en-v1.5');
    expect(T.env.localModelPath).toBe(tmp);
    expect(T.env.cacheDir).toBe(tmp);
    expect(T.env.allowRemoteModels).toBe(true);
    expect(r.local).toBe(false);
  });

  it('disables remote loading when that exact model is already local', () => {
    for (const file of ['tokenizer.json', 'config.json', path.join('onnx', 'model_quantized.onnx')]) {
      const target = path.join(tmp, BGE_EMBEDDER_REL, file);
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, 'ready');
    }
    const T = { env: {} };
    const r = configureTransformersModel(T, tmp, 'Xenova/bge-base-en-v1.5');
    expect(T.env.allowRemoteModels).toBe(false);
    expect(r.local).toBe(true);
  });

  it('materializes a complete pinned revision into the canonical offline path', () => {
    const model = 'Xenova/bge-base-en-v1.5';
    const revision = 'exact-sha';
    for (const file of ['tokenizer.json', 'config.json', path.join('onnx', 'model_quantized.onnx')]) {
      const target = path.join(tmp, BGE_EMBEDDER_REL, revision, file);
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, `pinned:${file}`);
    }
    expect(modelCacheReady(tmp, model)).toBe(false);
    expect(materializeModelRevision(tmp, model, revision)).toBe(true);
    expect(modelCacheReady(tmp, model)).toBe(true);
    expect(fs.readFileSync(path.join(tmp, BGE_EMBEDDER_REL, 'tokenizer.json'), 'utf8')).toBe('pinned:tokenizer.json');
  });

  it('serializes concurrent process materialization of one shared model cache', async () => {
    const model = 'Xenova/bge-base-en-v1.5';
    const revision = 'exact-sha';
    for (const file of ['tokenizer.json', 'config.json', path.join('onnx', 'model_quantized.onnx')]) {
      const target = path.join(tmp, BGE_EMBEDDER_REL, revision, file);
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, `pinned:${file}`);
    }
    const moduleUrl = new URL('../../kb/model-requirements.mjs', import.meta.url).href;
    const code = [
      `import { materializeModelRevision } from ${JSON.stringify(moduleUrl)};`,
      `if (!materializeModelRevision(${JSON.stringify(tmp)}, ${JSON.stringify(model)}, ${JSON.stringify(revision)})) process.exit(1);`,
    ].join('\n');
    const exits = await Promise.all(Array.from({ length: 4 }, () => new Promise((resolve) => {
      const child = spawn(process.execPath, ['--input-type=module', '--eval', code], { stdio: 'ignore' });
      child.once('exit', resolve);
    })));
    expect(exits).toEqual([0, 0, 0, 0]);
    expect(modelCacheReady(tmp, model)).toBe(true);
    expect(fs.existsSync(path.join(tmp, BGE_EMBEDDER_REL) + '.materialize-lock')).toBe(false);
  });
});

describe('classifyBattery — cold vs outage vs pass', () => {
  it('PASS: a valid in-threshold hit from the expected repo', () => {
    expect(classifyBattery({ repo: 'repo-a', repoOk: true, relOk: true, haveModel: true })).toBe('pass');
    // a hit is real evidence of a working model even if the cache check somehow disagreed
    expect(classifyBattery({ repo: 'repo-a', repoOk: true, relOk: true, haveModel: false })).toBe('pass');
  });

  it('COLD: no parseable hit AND the embedder model is absent', () => {
    expect(classifyBattery({ repo: undefined, repoOk: true, relOk: true, haveModel: false })).toBe('cold');
  });

  it('OUTAGE stays FAIL: no hit while the model IS present is a genuine retrieval failure, never cold', () => {
    // THE load-bearing assertion. If this ever returned 'cold', a real outage would be masked as a
    // benign cold cache — the exact dishonesty this whole change exists to prevent.
    expect(classifyBattery({ repo: undefined, repoOk: true, relOk: true, haveModel: true })).toBe('fail');
  });

  it('FAIL: a hit parsed but below the relevance floor, model present (real but wrong answer)', () => {
    expect(classifyBattery({ repo: 'repo-b', repoOk: true, relOk: false, haveModel: true })).toBe('fail');
  });
  it('FAIL: a hit parsed from the wrong repo, model present', () => {
    expect(classifyBattery({ repo: 'wrong-repo', repoOk: false, relOk: true, haveModel: true })).toBe('fail');
  });

  it('the ONLY thing that flips a no-hit fail→cold is the model disappearing from disk', () => {
    const noHit = { repo: undefined, repoOk: true, relOk: true };
    expect(classifyBattery({ ...noHit, haveModel: true })).toBe('fail');   // outage
    expect(classifyBattery({ ...noHit, haveModel: false })).toBe('cold');  // cold cache
    // and with the model present there is NO no-hit input that yields 'cold' — proven by construction:
    for (const repoOk of [true, false]) for (const relOk of [true, false]) {
      expect(classifyBattery({ repo: undefined, repoOk, relOk, haveModel: true })).not.toBe('cold');
    }
  });
});

// model-cache.mjs — cold-vs-warm model-cache detection for the capability battery.
//
// THE BUG THIS EXISTS TO KILL (docs/4.0-READINESS.md §6 item 1, ADR-028's empty-first house rule):
// the battery embeds every "can RuvNet do X?" question with the local MiniLM embedder
// (Xenova/all-MiniLM-L6-v2, 384-dim). On a machine where that model has never been downloaded,
// EVERY query fails — and the old battery rendered each failure as the SAME "(no hit)" a real
// retrieval outage prints. A healthy brain on a fresh machine looked broken, which is the exact
// anti-honesty the project forbids.
//
// The distinction is made EVIDENCE-BASED here — the embedder model file either exists on disk or it
// does not (the same evidence kb/resolve-deps.mjs configureModel() and bin/install.mjs already use):
//
//   COLD  — the embedder model file is ABSENT. First-run download not done. Expected on a fresh
//           machine; a "run once to warm it / set KB_MODEL_CACHE" condition, NOT a product fault.
//   FAIL  — the embedder model IS present, yet retrieval returned no valid hit. That is a genuine
//           outage/failure and MUST stay red. A cold cache may never mask a real outage: `cold`
//           requires BOTH no-hit AND model-absent, so with the model present a no-hit is always FAIL.
//
// resolveModelCache() MIRRORS plugin/mcp/server.mjs exactly (KB_MODEL_CACHE, else <BRAIN_HOME>/models)
// so the battery inspects the SAME path the MCP child loads the model from — the evidence is about
// the real door, not an adjacent one.

import path from 'node:path';
import os from 'node:os';
import {
  MINILM_MODEL,
  BGE_MODEL,
  requiredEmbedderModels,
  missingEmbedderModels,
} from '../../kb/model-requirements.mjs';

// The embedder the query side needs. The reranker (Xenova/ms-marco-MiniLM-L-6-v2) is a DIFFERENT
// model and its presence does not warm the query path — only this leaf makes queries answerable.
export { requiredEmbedderModels };
export const EMBEDDER_MODEL = MINILM_MODEL;
export const BGE_EMBEDDER_MODEL = BGE_MODEL;
export const EMBEDDER_REL = path.join(...EMBEDDER_MODEL.split('/'));
export const BGE_EMBEDDER_REL = path.join(...BGE_EMBEDDER_MODEL.split('/'));

// Same resolution the MCP server applies to the brain child (server.mjs:37,99):
//   BRAIN_HOME = RUVNET_BRAIN_HOME || ~/.cache/ruvnet-brain
//   modelCache = KB_MODEL_CACHE || <BRAIN_HOME>/models
// Env is read at call time (not import time) so tests can vary it deterministically.
export function resolveModelCache(env = process.env) {
  if (env.KB_MODEL_CACHE) return env.KB_MODEL_CACHE;
  const brainHome = env.RUVNET_BRAIN_HOME || path.join(os.homedir(), '.cache', 'ruvnet-brain');
  return path.join(brainHome, 'models');
}

// Read the query model from every installed RVF's own sidecar. Canonical Brain stores are BGE
// `*.big.rvf`; assuming MiniLM here made the release battery call itself warm while the real reader
// could not answer a single general query. An orphan sidecar is not a runtime requirement.
// The single piece of evidence: do ALL embedders required by the installed stores exist on disk?
export function modelPresent(modelCache = resolveModelCache(), models = [EMBEDDER_MODEL]) {
  try { return models.length > 0 && missingEmbedderModels(modelCache, models).length === 0; }
  catch { return false; }
}

// Classify one battery question's outcome. `haveModel` is the disk evidence above.
//   'pass' — a valid, in-threshold hit from the expected repo.
//   'cold' — NO parseable hit AND the embedder model is absent (cold cache — expected, not a fault).
//   'fail' — anything else while the model IS present: a genuine retrieval failure / outage.
// The asymmetry is deliberate and is what stops an outage masquerading as cold: if the model is
// present, a no-hit can NEVER be classified 'cold'.
export function classifyBattery({ repo, repoOk, relOk, haveModel }) {
  if (repo && repoOk && relOk) return 'pass';
  if (!repo && !haveModel) return 'cold';
  return 'fail';
}

